import{_ as i,l as r,o as e,c as l,v as t,p as s,x as o,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"物镜污染","description":"","frontmatter":{"title":"物镜污染","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/lens-contamination.md","filePath":"litho/lens-contamination.md","lastUpdated":1789023840000}'),c={name:"litho/lens-contamination.md"};function m(_,a,f,E,u,A){const n=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="物镜污染" tabindex="-1">物镜污染 <a class="header-anchor" href="#物镜污染" aria-label="Permalink to &quot;物镜污染&quot;">​</a></h1><div class="epigraph"><p>193 nm 把空气里的有机物打成膜，镀在镜头上：透过率掉、散射升、像差漂。污染是化学寿命，不是致密化。</p><footer>—— 对照 DUV 光学 carbon contamination；浸没末片的水痕与析出</footer></div><p><a href="/litho/birefringence-polarization">上一课</a>收束偏振。本课是物镜单元最后一课：表面脏。致密化在体里；污染在面上。下一单元工件台从机械另起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>净化空气仍有 ppb 级有机。193 nm 光解沉积碳氢膜，均匀性差时像加了一层随机相位。浸没末片还有水印、胶析出、气泡残骸。把透过率下降全写成气体寿命（激光），会去换错耗材。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>环境：化学过滤器、镜头吹扫。末片：浸没回收与清洗循环。监测：透过率/杂散光、定期像差。清洗有离线与在线限制，末片比内组容易够到。与 <a href="/litho/flare-and-stray">杂散光 flare</a> 相关：脏是 flare 的时间函数。</p>',7)),(e(),s(p,null,{default:o(()=>[h(n,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20ORG%5B%22%E6%9C%89%E6%9C%BA%20ppb%22%5D%20--%3E%20UV%5B%22193%20nm%20%E5%85%89%E8%A7%A3%22%5D%0A%20%20UV%20--%3E%20FILM%5B%22%E8%A1%A8%E9%9D%A2%E8%86%9C%22%5D%0A%20%20FILM%20--%3E%20T%5B%22%E9%80%8F%E8%BF%87%20%2F%20%E6%95%A3%E5%B0%84%22%5D%0A%20%20H2O%5B%22%E6%B5%B8%E6%B2%A1%E6%AE%8B%E7%95%99%22%5D%20--%3E%20FILM%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">EUV 多层污染是氢与锡的另一套化学，见 EUV 课，不要把 DUV 碳膜和锡滴混名。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>光子打断挥发有机，碎片吸附聚合。薄膜改反射/吸收，也改有效 \\(W\\)。颗粒则是局域缺陷，计量上像 flare 热点。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>工件台干涉仪和编码器的脏是下一单元，不是投影物镜。本课只管投影光路光学面。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>污染是表面光化学，与体致密化分账。</li><li>浸没末片多一条水与析出通道。</li><li>出处：DUV carbon contamination 通识；flare 课。</li></ul>',7))])}const B=i(c,[["render",m]]);export{T as __pageData,B as default};
